import { test } from "node:test";
import assert from "node:assert/strict";
import { APP_PAGES, FIXTURE_STRINGS, api, count, signUp, sql } from "./harness";

/**
 * A new account is shown its own data, and nobody else's.
 *
 * This is the suite that exists because of the bug. Every read in the
 * application used to fall back to a seeded workspace whenever it found
 * nothing — so somebody who had signed up a minute earlier saw Meridian's
 * projects, was greeted as Renata, and was shown 8,400 views and a retention
 * curve generated by a PRNG, all beside their own genuine zeros with nothing
 * on screen to tell the two apart.
 *
 * Each assertion here would have failed then.
 */

test("every page in a new workspace renders, and none shows another workspace's data", async () => {
  const session = await signUp("honesty");
  const failures: string[] = [];

  for (const path of APP_PAGES) {
    const response = await api(path, { cookie: session.cookie });

    // Both halves matter. An earlier version of this check looked only for
    // the strings and reported /app/analytics clean while that page was
    // returning 500 on every request — a page that does not render contains
    // nothing, which is not the same as one that renders honestly.
    if (response.status !== 200) {
      failures.push(`${path}: HTTP ${response.status}`);
      continue;
    }

    const html = await response.text();
    const hits = FIXTURE_STRINGS.filter((s) => html.toLowerCase().includes(s.toLowerCase()));
    if (hits.length > 0) failures.push(`${path}: contains ${hits.join(", ")}`);
  }

  assert.deepEqual(failures, [], `Pages failed the honesty check:\n  ${failures.join("\n  ")}`);
});

test("the dashboard greets the person who signed up, and counts nothing", async () => {
  const session = await signUp("greet");
  const html = await (await api("/app", { cookie: session.cookie })).text();

  // The name they typed, not the local part of their address and not a
  // fixture identity. The shell used to render "Renata Alves" until a viewer
  // arrived, and then the address's local part once one did.
  const first = session.name.split(" ")[0];
  assert.ok(
    html.includes(`Good morning, ${first}`) ||
      html.includes(`Good afternoon, ${first}`) ||
      html.includes(`Good evening, ${first}`),
    `The dashboard did not greet ${first} by name.`,
  );

  assert.ok(
    html.includes("No projects yet"),
    "An empty workspace should say it has no projects, not list somebody else's.",
  );
  assert.ok(
    html.includes("Nothing has been watched yet"),
    "With no views recorded, the views panel should say so rather than draw a sparkline.",
  );
});

test("analytics on a new workspace offers no chart and no invented curve", async () => {
  const session = await signUp("analytics");
  const html = await (await api("/app/analytics", { cookie: session.cookie })).text();

  assert.ok(
    html.includes("Nothing published yet"),
    "Analytics should show an empty state before anything is published.",
  );
  // The seeded curve always produced a largest drop, so this sentence
  // appeared on workspaces where no video had ever been opened.
  assert.ok(
    !html.includes("Largest drop"),
    "A retention drop was annotated for a workspace with no views.",
  );
});

test("a new workspace has exactly one member, and one audit entry", async () => {
  const session = await signUp("rows");

  assert.equal(
    count(`select count(*) from members where workspace_id = '${session.workspaceId}'`),
    1,
    "Signup should create exactly one member.",
  );
  assert.equal(
    count(
      `select count(*) from members where workspace_id = '${session.workspaceId}' and role = 'owner'`,
    ),
    1,
    "The first member owns the workspace — somebody has to be able to invite the second.",
  );
  assert.equal(
    count(`select count(*) from projects where workspace_id = '${session.workspaceId}'`),
    0,
    "A new workspace has no projects.",
  );
  assert.equal(
    sql(
      `select action from audit_events where workspace_id = '${session.workspaceId}' order by seq limit 1`,
    ),
    "workspace.created",
    "Creating a workspace should be in the audit log.",
  );
});

test("signing up twice with one address is refused, not silently merged", async () => {
  const session = await signUp("dupe");

  const again = await api("/api/auth/signup", {
    method: "POST",
    body: JSON.stringify({ email: session.email, name: "Somebody Else" }),
  });

  // Quietly logging somebody into an existing account because the address
  // matched is how one person ends up inside another company's workspace.
  assert.equal(again.status, 409, "A duplicate address should be refused.");
  assert.equal(
    count(`select count(*) from members where email = '${session.email}'`),
    1,
    "The refused signup must not have created a second member.",
  );
});

test("one workspace cannot read another's project, and cannot tell it exists", async () => {
  const owner = await signUp("tenant-a");
  const stranger = await signUp("tenant-b");

  const created = await api("/api/projects", {
    method: "POST",
    cookie: owner.cookie,
    body: JSON.stringify({ title: "Private walkthrough" }),
  });
  assert.equal(created.status, 201);
  const { project } = (await created.json()) as { project: { id: string } };

  const peek = await api(`/api/projects/${project.id}`, { cookie: stranger.cookie });
  // 404 rather than 403: a different answer for a project that exists in a
  // workspace you cannot see is an oracle for what that workspace contains.
  assert.equal(peek.status, 404, "A cross-tenant read should be indistinguishable from a miss.");

  const list = (await (await api("/api/projects", { cookie: stranger.cookie })).json()) as {
    data: unknown[];
  };
  assert.deepEqual(list.data, [], "The stranger's project list must be empty.");
});
